/* Altezza delle maiuscole: serve a centrare il testo dentro al riquadro
   invece di appoggiarlo sul bordo. Per i caratteri usati vale circa il 72%
   del corpo. */
function capHeightMm(sizePt) { return sizePt * 0.72 * 25.4 / 72; }

/* La linea di base che centra verticalmente un testo dentro al riquadro. */
function baselineFor(box, sizePt) {
    return box.y + box.h / 2 + capHeightMm(sizePt) / 2;
}

/* Corpo che riempie il riquadro senza toccarne i bordi: le maiuscole
   occupano circa i tre quarti dell'altezza utile, lasciando un margine
   sopra e sotto. In un riquadro da 4,1 mm significa circa 9 pt, contro i
   5,7 pt fissi della versione precedente — che dentro a quel riquadro
   lasciavano il testo alto poco più di un millimetro. Si riduce soltanto
   quando il contenuto è più largo dello spazio disponibile. */
function fitSize(box, testo, base) {
    let size = base || Math.min(10.5, Math.max(7, (box.h * 72 / 25.4) * 0.78));
    const larghezzaCarattere = s => s * 0.6 * 25.4 / 72;      // Courier: 0.6 em
    const lunghezza = String(testo || '').length;
    if (lunghezza) {
        const disponibile = box.w - 1.2;
        while (size > 5 && lunghezza * larghezzaCarattere(size) > disponibile) size -= 0.25;
    }
    return size;
}


const APP_VERSION="S15";const cents=v=>{if(v===undefined||v===null)return 0;if(!Number.isSafeInteger(v)||v<0)throw Error("Invalid cents");return v;};const fromCents=v=>v;
const normalizeId=v=>String(v??"").toUpperCase().replace(/[^A-Z0-9]/g,"");
const sectionedRows=g=>({erario:g.filled.filter(r=>r.section==="ERARIO"),inps:g.filled.filter(r=>r.section==="INPS")});
function pdfDocForGroup(g) {
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait', compress: true });
    const sections = sectionedRows(g);

    /* Scrive un valore centrato dentro al riquadro indicato. */
    const put = (box, valore, opzioni) => {
        const o = opzioni || {};
        const testo = String(valore ?? '').trim();
        if (!testo) return;
        const size = fitSize(box, testo, o.size);
        doc.setFont('courier', o.bold ? 'bold' : 'normal');
        doc.setFontSize(size);
        doc.setTextColor(17, 17, 17);
        const y = baselineFor(box, size);
        const align = o.align || box.align || 'center';
        const x = align === 'left' ? box.x + 0.6
                : align === 'right' ? box.x + box.w - 0.6
                : box.x + box.w / 2;
        doc.text(testo, x, y, { align });
    };

    /* Campi a caselle: una lettera per casella, centrata nella sua. */
    const putCells = (box, valore, { bold = true } = {}) => {
        const v = normalizeId(valore).slice(0, box.n);
        if (!v) return;
        const size = box.size || 10;
        doc.setFont('courier', bold ? 'bold' : 'normal');
        doc.setFontSize(size);
        doc.setTextColor(17, 17, 17);
        const y = baselineFor(box, size);
        for (let i = 0; i < v.length; i++) {
            doc.text(v[i], box.x + box.step * i + box.step / 2, y, { align: 'center' });
        }
    };

    /* Importi: euro allineati a destra prima della virgola stampata sul
       modello, centesimi nelle due caselle successive. */
    const putMoney = (box, valore, sizeBase) => {
        const n = cents(valore);
        if (n <= 0) return;
        const euro = String(Math.floor(n / 100));
        const cc = String(n % 100).padStart(2, '0');
        const size = Math.min(sizeBase || 9.5, fitSize({ w: MONEY_OFFSET.euroRight - 1.5, h: box.h }, euro, sizeBase || 9.5));
        doc.setFont('courier', 'normal');
        doc.setFontSize(size);
        doc.setTextColor(17, 17, 17);
        const y = baselineFor(box, size);
        doc.text(euro, box.x + MONEY_OFFSET.euroRight, y, { align: 'right' });
        doc.text(cc[0], box.x + MONEY_OFFSET.cent1, y, { align: 'center' });
        doc.text(cc[1], box.x + MONEY_OFFSET.cent2, y, { align: 'center' });
    };

    const putFlag = (box, attivo) => {
        if (!attivo) return;
        const size = 9;
        doc.setFont('courier', 'bold');
        doc.setFontSize(size);
        doc.setTextColor(17, 17, 17);
        doc.text('X', box.x + box.w / 2, baselineFor(box, size), { align: 'center' });
    };

    const totali = (key, sezione) => {
        const rr = sections[key] || [];
        const d = rr.reduce((a, r) => a + cents(r.debit), 0);
        const c = rr.reduce((a, r) => a + cents(r.credit), 0);
        const t = sezione.totali;
        putMoney({ ...COL_DEBIT, y: t.y, h: t.h }, fromCents(d));
        putMoney({ ...COL_CREDIT, y: t.y, h: t.h }, fromCents(c));
        if (t.saldo && rr.length) {
            const saldo = d - c;
            put({ x: 172.0, y: t.y, w: 3.0, h: t.h }, saldo < 0 ? '−' : '+', { size: 9, bold: true });
            putMoney({ ...COL_SALDO, y: t.y, h: t.h }, fromCents(Math.abs(saldo)));
        }
    };

    const first = g.filled && g.filled.length ? g.filled[0] : (g.rows[0] || {});
    const c = g.client || {};
    const data = (g.date || '').split('-');
    const iban = normalizeId(c.iban || '');
    const M = F24_MAP;

    for (let pagina = 0; pagina < 3; pagina++) {
        if (pagina) doc.addPage();
        doc.addImage(F24_MINISTERIAL_TEMPLATES[pagina], 'PNG', 0, 0, 210, 297, 'f24-' + pagina, 'FAST');

        /* Contribuente */
        putCells(M.contribuente.cf, c.cf || '', { bold: false });
        put(M.contribuente.name, c.name || '', { align: 'left' });
        put(M.contribuente.city, c.city || '', { align: 'left' });
        put(M.contribuente.province, c.province || '');
        put(M.contribuente.address, c.address || '', { align: 'left' });
        putFlag(M.contribuente.nonCalendarYear, first.nonCalendarYear);
        putCells(M.contribuente.coobligorCf, first.coobligorCf || '', { bold: false });
        put(M.contribuente.coobligorCode, first.coobligorCode || '');
        if (c.surname || c.firstName) {
            put(M.contribuente.firstName, c.firstName || '', { align: 'left' });
            const nascita = String(c.birthDate || '').split('-');
            if (nascita.length === 3) {
                put(M.contribuente.birthDay, nascita[2]);
                put(M.contribuente.birthMonth, nascita[1]);
                put(M.contribuente.birthYear, nascita[0]);
            }
            put(M.contribuente.sex, c.sex || '');
            put(M.contribuente.birthCity, c.birthCity || '', { align: 'left' });
            put(M.contribuente.birthProvince, c.birthProvince || '');
        }

        /* Sezioni */
        Object.entries(M.sezioni).forEach(([key, sezione]) => {
            const righeSezione = (sections[key] || []).slice(0, sezione.rows.length);
            righeSezione.forEach((r, i) => {
                const top = sezione.rows[i];
                Object.entries(sezione.cols).forEach(([campo, col]) => {
                    if (col.soloPrimaRiga && i > 0) return;
                    const box = { x: col.x, y: top, w: col.w, h: sezione.h, align: col.align };
                    if (col.t === 'money') putMoney(box, r[campo]);
                    else if (col.t === 'flag') putFlag(box, r[campo]);
                    else if (campo === 'periodFrom' || campo === 'periodTo') put(box, r[campo] || (campo === 'periodFrom' ? r.period : ''));
                    else put(box, r[campo]);
                });
            });
            if (sezione.extra) {
                const prima = righeSezione[0] || {};
                Object.entries(sezione.extra).forEach(([campo, box]) => {
                    const valore = campo === 'operationId'
                        ? (righeSezione.find(r => r.operationId) || {}).operationId
                        : campo === 'detrazione'
                            ? righeSezione.reduce((s, r) => s + cents(r.detrazione), 0) / 100
                            : prima[campo];
                    if (box.t === 'cells') putCells(box, valore || '');
                    else if (box.t === 'money') putMoney(box, valore);
                    else put(box, valore);
                });
            }
            totali(key, sezione);
        });

        /* Saldo finale, data e IBAN */
        putMoney(M.saldoFinale, Math.abs(g.balance), 10);
        if (data.length === 3) {
            putCells(M.versamento.day, data[2]);
            putCells(M.versamento.month, data[1]);
            putCells(M.versamento.year, data[0]);
        }
        if (pagina === 0 && iban) {
            putCells(M.versamento.iban, iban.startsWith('IT') ? iban.slice(2) : iban);
        }
    }


    doc.setProperties({
        title: `Modello F24 — ${g.client.name || 'Contribuente'} — ${g.date || ''} — Flusso ${g.flow}`,
        subject: 'Modello F24 ordinario ministeriale in tre copie',
        author: 'Tax Automation Lab',
        creator: `Generatore F24 v${APP_VERSION}`
    });
    return doc;
}


export function renderF24Pdf(taxpayer,group){
if(!["READY","DOWNLOADED","PAID"].includes(group.status)||group.lines.length<1||group.lines.filter(l=>l.section==="ERARIO").length>6||group.lines.filter(l=>l.section==="INPS").length>4)throw Error("F24 not ready");
let sum=0;const rows=group.lines.map(l=>{if(!Number.isSafeInteger(l.amountCents)||l.amountCents<=0)throw Error("Unsupported row");const base={section:l.section,taxCode:l.taxCode,debit:l.amountCents,credit:0};sum+=l.amountCents;if(l.section==="ERARIO"&&["1790","1791","1792"].includes(l.taxCode))return {...base,period:l.period,year:String(l.referenceTaxYear)};if(l.section==="INPS"&&["PXX","P10","AP","CP","AF","CF"].includes(l.taxCode)&&/^\d{4}$/.test(l.officeCode)&&/^\d{6}$/.test(l.periodFrom)&&/^\d{6}$/.test(l.periodTo)&&(["PXX","P10"].includes(l.taxCode)?l.inpsCode==="":/^\d{17}$/.test(l.inpsCode)))return {...base,officeCode:l.officeCode,reference:l.inpsCode,periodFrom:l.periodFrom,periodTo:l.periodTo};throw Error("Unsupported row");});
if(!Number.isSafeInteger(sum)||sum!==group.totalCents)throw Error("Totals mismatch");
return pdfDocForGroup({client:taxpayer,filled:rows,rows,balance:sum,date:"",flow:"S15"});}
